query:
-- IA-1: Christina Bohannan won Dem primary
UPDATE house_races SET candidate1_name = 'Christina Bohannan', status = 'General' WHERE state_code = 'IA' AND district = '1';

-- IA-2: Lindsay James (D) vs Joe Mitchell (R) — both won primaries
UPDATE house_races SET candidate1_name = 'Lindsay James', candidate1_party = 'D', candidate2_name = 'Joe Mitchell', candidate2_party = 'R', status = 'General' WHERE state_code = 'IA' AND district = '2';

-- IA-3: Sarah Trone Garriott (D) vs Zach Nunn (R) — Garriott won Dem primary
UPDATE house_races SET candidate1_name = 'Sarah Trone Garriott', status = 'General' WHERE state_code = 'IA' AND district = '3';

-- IA-4: Dave Dawson (D) vs Chris McGowan (R) — Feenstra vacated for Gov race
UPDATE house_races SET candidate1_name = 'Dave Dawson', candidate1_party = 'D', candidate2_name = 'Chris McGowan', candidate2_party = 'R', status = 'General' WHERE state_code = 'IA' AND district = '4';

-- MT-1: Sam Forstag (D) vs Aaron Flint (R) — Zinke retired
UPDATE house_races SET candidate1_name = 'Sam Forstag', candidate1_party = 'D', candidate2_name = 'Aaron Flint', candidate2_party = 'R', status = 'General' WHERE state_code = 'MT' AND district = '1';

-- NJ-7: Rebecca Bennett (D) vs Thomas Kean Jr. (R)
UPDATE house_races SET candidate1_name = 'Rebecca Bennett', candidate1_party = 'D', status = 'General' WHERE state_code = 'NJ' AND district = '7';

-- NJ-12: Adam Hamawy (D) — Watson Coleman retiring
UPDATE house_races SET candidate1_name = 'Adam Hamawy', candidate1_party = 'D', status = 'General' WHERE state_code = 'NJ' AND district = '12';

-- SD-AL: Marty Jackley (R) — Dusty Johnson vacated for Senate
UPDATE house_races SET candidate2_name = 'Marty Jackley', candidate2_party = 'R', status = 'General' WHERE state_code = 'SD' AND district = '0';

